def makeChange(coinSet, change):
    bestSet = []
    for i in range(change + 1):
        bestSet.append([i])

    # populate the list until the change amount
    for i in range(1, change + 1):
        for j in range(len(coinSet)):
            # test to see if the coin is less then or equal to the change
            if coinSet[j] <= i:
                bestSet[i] = min(bestSet[i], 1 + bestSet[i - coinSet[j]])

    # check to make sure the coins sum upto given amount else return None
    if(sum(bestSet[change]) != change):
        return None

    return bestSet[change]
